import {leaveLabels} from './leave-contract.mjs';
import {closureBlockers} from './closure-contract.mjs';
import {monthlyStates} from './monthly-contract.mjs';
export function createClosureViews({api,h,showPanel,localTime,writable,getUser,onAction}){
 const title=a=>a==='lock'?'核定并锁定':'重新开放核定',fmt=t=>t?localTime(t):'未登记';
 async function detail(id){await showPanel('考勤核定版本',async signal=>{const r=await api.closureDetail(id,signal),c=r.snapshot;return `<div class="dialog-header"><h2>${h(r.month)} · 第 ${r.revision} 版</h2><button class="icon-button" data-attendance-close aria-label="关闭核定详情">×</button></div><p>${h(title(r.action))} · ${h(r.actor_name)} · ${h(fmt(r.created_at))}</p><p class="preserve-text">${h(r.note)}</p>${c?`<h3>${h(c.member.name)} · 当次锁定快照</h3><p class="planning-rule">以下为历史快照；本页不会跟随后续数据变化。是否仍为有效锁定依据，请查看月度页面的当前状态。</p><dl class="record-facts">${[['计划工作日',c.summary.expectedDays],['正常工作日',c.summary.normalDays],['迟到',c.summary.lateDays],['时长不足',c.summary.insufficientDays],['批准请假涉及天数',c.summary.leaveDays],['批准请假区间分钟',c.summary.leaveMinutes],['无记录待核实',c.summary.unverifiedAbsenceDays],['批准补卡',c.summary.approvedCorrections],['记录待核对',c.summary.needsReviewDays]].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(v)}</dd></div>`).join('')}</dl>${c.days.map(d=>`<article class="observation"><b>${h(d.date)} · ${d.workday?'工作日':'休息日'} · ${h(monthlyStates[d.state])}</b><p>核准：${h(fmt(d.inAt))} → ${h(fmt(d.outAt))}</p>${d.periods.map(p=>`<p>原始：${h(fmt(p.original_in))} → ${h(fmt(p.original_out))}</p>`).join('')}${d.calendar.note?`<p class="preserve-text">日历说明：${h(d.calendar.note)}</p>`:''}${r.day_notes.find(n=>n.date===d.date)?`<p class="preserve-text">当次核对说明：${h(r.day_notes.find(n=>n.date===d.date).note)}</p>`:''}${d.leaves.map(l=>`<p>${h(l.type)} · ${l.status==='approved'?'已批准':'待审核'} · ${l.minutes} 分钟</p>`).join('')}</article>`).join('')}`:'<p>此版本已重新开放核定，原锁定内容保留在此前版本中。</p>'}${c?`<h3>当次审核来源</h3>${c.sourceFacts.reviews.map(r=>`<article class="observation"><b>${r.kind==='late'?'迟到':'时长不足'} · ${h(r.actor_name)}</b><p class="preserve-text">${h(r.note)}</p><p>来源工作段版本 ${r.period_version} · 核实第 ${r.revision} 版</p></article>`).join('')||'<p class="muted">没有时间异常核实记录。</p>'}${c.sourceFacts.leaves.map(l=>`<article class="observation"><b>${h(l.leave_type)} · ${h(leaveLabels[l.status])}</b><p>${h(fmt(l.starts_at))} → ${h(fmt(l.ends_at))}</p><p class="preserve-text">${h(l.review_note||l.reason)}</p></article>`).join('')}`:''}${r.previous_id?`<button class="secondary" data-closure-detail="${h(r.previous_id)}">查看此前版本</button>`:''}`;});}
 async function history(month,memberId,offset=0){await showPanel('考勤月份核定历史',async signal=>{const v=await api.closureHistory(month,memberId,offset,signal);return `<div class="dialog-header"><h2>${h(month)} · 核定历史</h2><button class="icon-button" data-attendance-close aria-label="关闭核定历史">×</button></div>${v.rows.map(r=>`<button class="asset-row" data-closure-detail="${h(r.id)}"><span><b>第 ${r.revision} 版 · ${h(title(r.action))}</b><small>${h(r.actor_name)} · ${h(fmt(r.created_at))}</small><small>${h(r.note)}</small></span><span>查看 ›</span></button>`).join('')||'<p class="muted">尚无核定记录。</p>'}<div class="pager"><button class="secondary" data-closure-history="${h(month)}" data-member="${h(memberId)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-closure-history="${h(month)}" data-member="${h(memberId)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 document.addEventListener('click',e=>{const d=e.target.closest('[data-closure-detail]'),a=e.target.closest('[data-closure-action]'),hs=e.target.closest('[data-closure-history]');if(d)detail(d.dataset.closureDetail);if(a)onAction(a.dataset.month,a.dataset.member,a.dataset.closureAction);if(hs)history(hs.dataset.closureHistory,hs.dataset.member,Number(hs.dataset.offset||0));});
 return {card(s){const c=s.current;if(!c.member)return '';return `<section class="planning-rule"><h3>${s.status==='locked'?(s.drift?'已锁定，来源已有变化':'已锁定，来源一致'):s.status==='reopened'?'已重新开放，等待核定':'尚未核定锁定'}</h3><p>下方为当前动态汇总。锁定版本独立保留，原记录后续仍可补正；变化后需要重新核定，不能悄悄沿用旧版作为工资依据。</p>${s.latest?`<p>最近操作：${h(title(s.latest.action))} · ${h(s.latest.actor_name)} · ${h(fmt(s.latest.created_at))}</p>`:''}${s.status!=='locked'&&s.blockers.length?`<ul>${s.blockers.map(k=>`<li>${h(closureBlockers[k])}</li>`).join('')}</ul>`:''}${s.status!=='locked'&&s.requiredDates.length?`<p>${s.requiredDates.length} 个特殊日期需要逐日核对说明，原有时间与状态保留。</p>`:''}<div class="action-row">${writable&&getUser()?.role==='admin'?s.status==='locked'?`<button class="secondary" data-closure-action="reopen" data-month="${h(c.month)}" data-member="${h(c.member.id)}">说明原因并重新开放</button>`:`<button class="primary" data-closure-action="lock" data-month="${h(c.month)}" data-member="${h(c.member.id)}" ${s.blockers.length?'disabled':''}>核定并锁定本月</button>`:''}${s.latest?`<button class="secondary" data-closure-detail="${h(s.latest.id)}">查看最近核定版本</button>`:''}<button class="secondary" data-closure-history="${h(c.month)}" data-member="${h(c.member.id)}">核定历史</button></div></section>`;}};
}
